#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Generate deterministic binary plist protocol fixtures (not firmware assets)."""
import pathlib
import plistlib
base = {"type": 100, "streamConnectionID": 9000, "audioFormat": 0x20000000,
        "audioType": "speechRecognition", "dataPort": 50000, "input": True,
        "framesPerPacket": 960}
fixtures = {
    "audio_type_teardown": {"streams": [{"type":100}]},
    "media_setup": {"streams": [{"type":100,"streamConnectionID":9001,"audioFormat":0x800,"audioType":"media"}]},
    "voice_stop": {"streams": [{"type":100,"streamConnectionID":9000,"audioType":"speechRecognition"}]},
    "voice_stale_stop": {"streams": [{"type":100,"streamConnectionID":8999,"audioType":"speechRecognition"}]},
    "voice_setup": {"streams": [base]},
    "voice_bad_port": {"streams": [dict(base, dataPort=65536)]},
    "voice_changed_format": {"streams": [dict(base, audioFormat=0x40000000)]},
    "duplicate_audio_keys": {"streams": [base, dict(base, type=101)]},
    "voice_modes": {"type": "modesChanged", "params": {"appStates": [
        {"appStateID": 2, "entity": 1}, {"appStateID": 1, "speechMode": 2}],
        "resources": [{"resourceID": 2, "entity": 1}]}},
    "voice_bad_modes": {"type": "modesChanged", "params": {"appStates": "invalid"}},
    "voice_duck": {"type": "duckAudio", "params": {"volume": -18.0, "durationMs": 250}},
    "voice_unduck": {"type": "unduckAudio", "params": {"durationMs": 100}},
    "voice_bad_duck": {"type": "duckAudio", "params": {"volume": float("nan")}},
    "voice_bad_duration": {"type": "duckAudio", "params": {"durationMs": -1}},
}
output = ["/* SPDX-License-Identifier: GPL-3.0-or-later; generated by generate-session-fixtures.py */"]
for name, value in fixtures.items():
    data = plistlib.dumps(value, fmt=plistlib.FMT_BINARY, sort_keys=False)
    output.append("static const uint8_t k_" + name + "[] = {")
    output.extend("    " + ",".join(f"0x{b:02x}" for b in data[i:i+16]) + "," for i in range(0, len(data), 16))
    output.append("};")
pathlib.Path(__file__).with_name("session-fixtures.h").write_text("\n".join(output)+"\n")
